<?php require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{if(($_POST['action']??'save')==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare("SELECT cover_path FROM posts WHERE id=?");$st->execute([$id]);$old=(string)$st->fetchColumn();$pdo->prepare("DELETE FROM posts WHERE id=?")->execute([$id]);delete_local_media($old);go('noticias.php','Notícia removida.');}$cover='';if(!empty($_FILES['cover']['name']))$cover=upload_file($_FILES['cover'],'image');$pdo->prepare("INSERT INTO posts(title,summary,content,cover_path,published,created_at) VALUES(?,?,?,?,?,?)")->execute([trim($_POST['title']??''),trim($_POST['summary']??''),trim($_POST['content']??''),$cover,isset($_POST['published'])?1:0,now_iso()]);go('noticias.php','Notícia publicada.');}catch(Throwable $e){$err=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM posts ORDER BY created_at DESC")->fetchAll();admin_header('Notícias');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<form class="panel form-stack" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Título<input name="title" required></label><label>Resumo<textarea name="summary"></textarea></label><label>Texto completo<textarea name="content" rows="10"></textarea></label><label>Capa<input type="file" name="cover" accept="image/*"></label><label class="check"><input type="checkbox" name="published" checked> Publicar</label><button class="primary">PUBLICAR NOTÍCIA</button></form>
<div class="records"><?php foreach($rows as $r):?><article><?php if($r['cover_path']):?><img src="../<?=e($r['cover_path'])?>" alt=""><?php endif;?><div><span><?=e($r['created_at'])?></span><h3><?=e($r['title'])?></h3><p><?=e($r['summary'])?></p></div><form method="post" onsubmit="return confirm('Excluir?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Excluir</button></form></article><?php endforeach;?></div><?php admin_footer();?>
